import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  root: { color: 'blue', fontSize: '14px', marginInlineStart: '8px' },
});

import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  root: { color: { default: 'blue', ':hover': 'red' } },
});

import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  root: { color: { default: 'blue', '@media (min-width: 600px)': { default: 'green', ':hover': 'red' } } },
});

import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  root: { color: null, margin: 0 },
});

import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  one: { color: 'blue' },
  two: { color: 'red', fontSize: '14px' },
  three: { display: 'flex' },
});

import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  root: { content: 'hello', color: 'red' },
});

import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  root: { position: ['sticky', 'fixed'] },
});

import * as stylex from '@stylexjs/stylex';
import { breakpoints, spacing } from './tokens.stylex';
export const styles = stylex.create({
  root: { color: { default: 'red', [breakpoints.md]: 'blue' }, padding: spacing.gutter },
});

import * as stylex from '@stylexjs/stylex';
const fade = stylex.keyframes({ from: { opacity: 0 }, to: { opacity: 1 } });
export const styles = stylex.create({
  root: { animationName: fade, animationDuration: '500ms' },
});

import * as stylex from '@stylexjs/stylex';
import { getColor } from './helpers';
export const styles = stylex.create({
  root: { color: getColor() },
});

import * as stylex from '@stylexjs/stylex';
const more = { extra: { color: 'green' } };
export const styles = stylex.create({
  root: { color: 'red' },
  ...more,
});

import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  root: { color: stylex.firstThatWorks('var(--a)', 'red', 'var(--b)', 'blue') },
});
